export default function App(){const pages=[['/dashboard',<Dashboard/>],['/evaluate',<EvaluatePage/>],['/history',<HistoryPage/>],['/wishlist',<CoolingOffPage/>],['/compare',<ComparePage/>],['/rules',<ShoppingRulesPage/>],['/owned-items',<OwnedItems/>],['/budget',<BudgetPlannerPage/>],['/goals',<GoalsPage/>],['/subscriptions',<SubscriptionsPage/>],['/smart-capture',<SmartCapturePage/>],['/reports',<ReportsPage/>],['/coach',<CoachPage/>],['/notifications',<NotificationsPage/>],['/security',<SecurityPage/>],['/profile',<Profile/>]];return <Routes><Route path="/login" element={<Auth/>}/><Route path="/register" element={<Auth signup/>}/><Route path="/forgot-password" element={<ForgotPassword/>}/><Route path="/reset-password" element={<ResetPassword/>}/>{pages.map(([path,page])=><Route key={path} path={path} element={<Guard>{page}</Guard>}/>)}<Route path="*" element={<Navigate to={current()?'/dashboard':'/login'}/>}/></Routes>}
